@lru_cache(maxsize=None)
def sk(n, k):
    if n == 0:
        return 1
    return (k * sk(n // k, k) + n) % (10**9 + 7)

@lru_cache(maxsize=None)
def fibonacci(n):
    if n == 0:
        return 0
    elif n <= 2:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

@lru_cache(maxsize=None)
def sk2(n, k):
    return 1 + (2 * k - 1) * fibonacci(n) % (10**9 + 7)

