            if arr[i] != prev_heights[i]:
                duration += 1
        prev_heights = temp[:]
        if arr == prev_heights:
            break
    return duration

def find_stabilization_heights(arr):
    max_height = 0
    h = heapq.heapify(arr)
    maximum = 0
    for i in range(len(arr)):
        heapq.heappop(h)
        if i >= 2:
            heapq.heappush(h, arr[i-2])
        if len(h) == 3:
            maximum = max(max_height, h[0])
        heapq.heappush(h, arr[i])
