def count_paths(s):
    ways = [0] * (s + 1)
    ways[0] = 1  # Base case: zero path matches

    for i in range(1, int(s**0.5) + 1):
        if i * i <= s:
            ways[i * i] += ways[i]  # Parent case

    mult = 2
    for i in range(2, int(s**0.5) + 1):
        nxt = i * (i + 1)
        ways[nxt] += ways[i] * i  # Rule 1

    for pair_size in range(2, int(s**0.5) + 1):
        if (pair_size + 1) * pair_size <= s:
            ways[(pair_size + 1) * pair_size] += ways[pair_size]
        nxt = (pair_size - 1) * pair_size + 1
        ways[nxt] += ways[pair_size] * pair_size  # Rule 2

    for i in range(1, int(s + 1) // 2):
        ways[i * 2 + 1] += ways[i] * (i + 1) // 2 * (s + 1 - (i + 1) * 2)  # Rule 3

    count = sum([(s - ii) // joint for ii, joint in enumerate(ways)])
    return count
