def monotone_free_subseq(l, r, sequence):
    maximum_length, current_length, found = 1, 1, False
    current_start = l - 1

    for i in range(l, r):
        if sequence[i] == sequence[current_start]:
            current_length += 1
        else:
            current_length = 2
            current_start = i
        if current_length > maximum_length:
            maximum_length = current_length
            found = True
        elif current_length >= 3 and sequence[current_start] < sequence[i] and found:
            return 0

    if not found:
        return maximum_length

    # Find the rightmost monotone triples
    increase_index, total_length = l - 1, 0
    decrease_index, total_length_decrease = r, 0
    while increase_index + 2 < r and sequence[increase_index] < sequence[increase_index + 1] < sequence[increase_index + 2]:
        increase_index += 1
    total_length += (increase_index + 1 - current_start) * 2
    if sequence[increase_index] == sequence[i]:
        total_length += 2
    else:
        total_length += 1

    while decrease_index - 2 > l - 1 and sequence[decrease_index] > sequence[decrease_index - 1] > sequence[decrease_index - 2]:
        decrease_index -= 1
    total_length += (r - decrease_index - 1) * 2
    if sequence[decrease_index] == sequence[i]:
        total_length += 2
    else:
        total_length += 1

    return maximum_length, int(total_length / 2)

