def stabilize_mountain_range(mountain_heights, n):
    alignments = 0
    i = 1
    while i < n - 1:
        current = mountain_heights[i]
        left_median, right_median = 0, 0
        left_median_pos = 0
        right_median_pos = n - 1
        total_heights = mountain_heights[:i] + mountain_heights[i + 1:]

        while left_median_pos <= right_median_pos:
            if left_median_pos == right_median_pos:
                if total_heights[left_median_pos] < current:
                    left_median = total_heights[left_median_pos]
                    left_median_pos += 1
                elif total_heights[left_median_pos] > current:
                    right_median = total_heights[right_median_pos]
                    right_median_pos -= 1
                else:
                    break
            else:
                left_height = (total_heights[left_median_pos] + total_heights[left_median_pos-1]) / 2
                right_height = (total_heights[right_median_pos] + total_heights[right_median_pos+1]) / 2

                if left_height < current < right_height:
                    break
                elif current < left_height:
                    right_median, right_median_pos = right_height, right_median_pos + 1
                elif current > right_height:
                    left_median, left_median_pos = left_height, left_median_pos - 1
                else:
                    break

        total_heights[left_median_pos] = current
        if left_median < current < right_median:
            total_heights[right_median_pos + 1] = current
        elif current < left_median:
            total_heights[left_median_pos - 1] = current
        else:
            total_heights[right_median_pos + 1] = current

        mountain_heights[0] = current
        mountain_heights[n-1] = current
        mountain_heights[i] = complex(left_median, 0) if left_median >= current else complex(0, -right_median)
        mountain_heights[i+1] = complex(0, -current) if right_median > current else complex(current, 0)
        mountain_heights[i] = complex(mountain_heights[i].real, mountain_heights[i].imag)
        mountain_heights[i+1] = complex(mountain_heights[i+1].real, mountain_heights[i+1].imag)

        alignments += 1
        i += 1

    return alignments, mountain_heights[:i] + mountain_heights[n-1:]

