from collections import defaultdict, deque

def get_min_sets(k, tree):
    n = len(tree)
    parent = [-1] * n
    dist = [-1] * n
    dist[0] = 0

    for node in range(n - 1):
        edges = tree[node]
        for i in edges:
            child = i
            parent[child] = edges[0] if edges[0] < edges[1] else edges[1]
            dist[child] = dist[parent[child]] + 1

    def is_leaves_and_dist_known(v, k, g):
        return dist[v] <= k and not g[v]

    def dfs(v, q, g):
        for to in g[v]:
            if not is_leaves_and_dist_known(to, k, g):
                q.append(v)
                dfs(to, q, g)
        return q

    def bt(v, k, g):
        seen = [False] * n
        seen[v] = True
        current = deque((v, k, q := tuple(seen)))
        g_size = 0
        if any(is_leaves_and_dist_known(i, k, g) for i in q):
            g_size += 1

        while current:
            parent, level, q = current.popleft()
            dist[parent] = level
            for child in g[parent]:
                if not seen[child]:
                    seen[child] = True
                    current.append((child, level - 1, q + (seen[child],)))

        return g_size

    return bt(0, k, defaultdict(set))

