import math

def find_square_divisor(N, factors):
    for prime in range(2, int(math.sqrt(max(factors))) + 1):
        count = 0
        for factor in factors:
            if factor % (prime ** 2) == 0:
                count += 1
            while factor % prime == 0:
                factor //= prime
        if count == len(factors):
            return prime
    return None

