from collections import defaultdict

def count_balanced_triples(n, k, skills, flips):
    # Initialize balance counts for each skill level
    skill_balance = defaultdict(int)
    skill_changes = defaultdict(int)
    i = 0

    for skill in skills:
        skill_balance[skill] += 1
        while i < len(flips):
            ai, bi = flips[i]
            if ai <= skill <= bi:
                skill_changes[ai, bi] += 1
                break
            i += 1

    total_triples = 0
    for balance in skill_balance.values():
        for i in range(1, balance + 1):
            complement = balance - i
            for x in range(max(0, balance - 4 * i), min(balance + i, 2 * balance)):
                for y in range(x + 1, min(balance + 4 * (balance / complement) - i, 2 * balance + 1)):
                    for z in range(y + 1, min(balance + 3 * (balance / i) - i, 2 * balance + 2)):
                        if (z + i) % 2 == 0 and i <= z < (z + i) // 2 and (i + balance // complement) <= z < z + i:
                            total_triples += skills[x] > skills[y] and skills[y] > skills[z] and skills[z] > skills[x]

    return total_triples

