from math import gcd
from fractions import Fraction

def calculate_probability(counts):
    if counts[0] == 1:
        return Fraction(0, 1)
    else:
        return Fraction(counts[0], counts[0] + 1)

def main():
    T = int(input())
    for _ in range(T):
        n = int(input())
        numbers = list(map(int, input().split()))

        if n < 25:
            counts = [1, 1]
            for i in range(n):
                counts[1] += numbers[i]
            result = calculate_probability(counts)
        else:
            random_probability = Fraction(1, 101)
            seq = sorted(numbers) + [0]
            for i in range(1, n + 1):
                sequence = [0] * i
                for j in seq:
                    for k in range(len(sequence), i):
                        sequence[k] = gcd(sequence[k] % 26 + 1, j)
                counts = sum(1 for item in sequence if item), sum(numbers) - sum(counts[0:i])
                random_probability *= calculate_probability(counts)
            result = random_probability * 1247
        print(f"{int(result.numerator)} {result.denominator} {result.numerator * 10000 // result.denominator:.4f}")

if __name__ == "__main__":
    main()
